### 2. Give parallel workers separate accounts

`storageState` creates separate browser contexts, but it does **not** create separate server-side users. Assign a unique account to each worker, and have each test set the language it expects before asserting it. The account pool must contain at least as many accounts as the maximum number of parallel workers.

For a single project, a worker-scoped storage-state fixture can log in each account once:

```ts
// playwright/worker-test.ts
import { test as base, expect } from '@playwright/test';
import { rm } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

type Account = { username: string; password: string };
type WorkerFixtures = { workerStorageState: string };

const accounts = JSON.parse(
  process.env.PW_ACCOUNTS ?? '[]',
) as Account[];

export const test = base.extend<{}, WorkerFixtures>({
  storageState: async ({ workerStorageState }, use) => {
    await use(workerStorageState);
  },

  workerStorageState: [async ({ browser }, use, workerInfo) => {
    const account = accounts[workerInfo.parallelIndex];
    if (!account) {
      throw new Error(`No account for worker ${workerInfo.parallelIndex}`);
    }

    const baseURL = workerInfo.project.use.baseURL;
    if (typeof baseURL !== 'string') {
      throw new Error('Set use.baseURL in the Playwright config');
    }

    const statePath = path.join(
      os.tmpdir(),
      `pw-${workerInfo.project.name}-${workerInfo.parallelIndex}.json`,
    );

    const context = await browser.newContext();
    try {
      const page = await context.newPage();
      await page.goto(new URL('/login', baseURL).toString());
      await page.getByLabel('Username').fill(account.username);
      await page.getByLabel('Password').fill(account.password);
      await page.getByRole('button', { name: 'Sign in' }).click();
      await page.waitForURL('**/');

      await context.storageState({ path: statePath });
    } finally {
      await context.close();
    }

    try {
      await use(statePath);
    } finally {
      await rm(statePath, { force: true });
    }
  }, { scope: 'worker' }],
});

export { expect };
```

Import `test` from this file in those specs instead of `@playwright/test`. If you have multiple projects, make sure their workers also get distinct accounts. Avoid sharing one account across parallel workers; serializing the language-changing tests is an alternative if they must share an account.

